"""Build the three engineering reports using the shared case-study layout."""
from pathlib import Path
from html import escape
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
PROJECTS = ROOT/'assets/projects'
original_css = PROJECTS/'Pr04-Orbit-Analyzer/orbit.css'
shared_css = ROOT/'assets/css/project-report.css'
if not original_css.read_text(encoding='utf-8').startswith('@import'):
    css = original_css.read_text(encoding='utf-8')
    css = css.replace('.orbit-case figure', '.orbit-case main figure').replace('.orbit-case figcaption', '.orbit-case main figcaption')
    shared_css.write_text(css.replace('.orbit-case', ':is(.orbit-case, .project-report)'), encoding='utf-8')
    original_css.write_text('@import url("../../css/project-report.css");\n', encoding='utf-8')

folder = ''
def figure(src, caption):
    w, h = Image.open(PROJECTS/folder/src).size
    return f'<figure><a href="{src}" aria-label="Open image: {escape(caption)}"><img src="{src}" width="{w}" height="{h}" loading="lazy" decoding="async" alt="{escape(caption)}"></a><figcaption>{escape(caption)} <span>Select image to enlarge.</span></figcaption></figure>'

def gallery(items):
    return '<div class="report-gallery">'+''.join(figure(*item) for item in items)+'</div>'

def table(caption, headers, rows):
    return '<div class="table-wrap"><table><caption>'+caption+'</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def section(key, title, content):
    return (key, title, content)

def render(name, title, subtitle, category, lead, tags, hero, stats, sections, resource):
    toc=''.join(f'<a href="#{key}">{i:02} / {heading}</a>' for i,(key,heading,_) in enumerate(sections,1))
    body=''.join(f'<section class="case-section" id="{key}"><p class="case-kicker">{i:02} / {heading}</p><h2>{heading}</h2>{content}</section>' for i,(key,heading,content) in enumerate(sections,1))
    stat_html=''.join(f'<div><dt>{value}</dt><dd>{label}</dd></div>' for value,label in stats)
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | Mahmoud Samhoud</title><meta name="description" content="{escape(lead)}"><script src="../../js/theme-init.js"></script><link rel="icon" href="../../img/favicon.png"><link rel="stylesheet" href="../../vendor/bootstrap-icons/bootstrap-icons.css"><link rel="stylesheet" href="../../css/main.css"><link rel="stylesheet" href="../../css/project-report.css"></head>
<body class="project-report"><a class="skip-link" href="#content">Skip to project</a><header class="case-nav"><a class="case-brand" href="../../../index.html">MS<span> / Engineering portfolio</span></a><nav aria-label="Project navigation"><a href="../../../index.html#portfolio">All projects</a><a href="#overview">Project overview</a></nav></header>
<main id="content"><section class="case-hero"><p class="case-kicker">{category}</p><h1>{title}<span>{subtitle}</span></h1><p class="case-lead">{lead}</p><div class="case-tags">{''.join('<span>'+tag+'</span>' for tag in tags)}</div><div class="case-actions"><a class="case-button" href="#{sections[1][0]}">Explore the project ↓</a><a href="{resource[0]}" target="_blank" rel="noopener">{resource[1]} ↗</a></div></section>
{figure(*hero)}<dl class="case-stats">{stat_html}</dl><div class="case-layout"><aside class="case-toc"><p>IN THIS PROJECT</p><nav aria-label="Documentation sections">{toc}</nav></aside><article>{body}</article></div>
<section class="case-callout"><p class="case-kicker">Project resources</p><h2>Explore the supporting work.</h2><div class="case-actions"><a class="case-button" href="{resource[0]}" target="_blank" rel="noopener">{resource[1]} ↗</a><a href="../../../index.html#portfolio">Back to selected work</a></div></section></main>
<footer class="case-footer"><p>Mahmoud Samhoud <span> / {category.split(' / ')[0]}</span></p><a href="../../../index.html#portfolio">Explore more projects ↗</a></footer><script src="../../js/main.js"></script></body></html>'''
    html = html.replace('../../js/main.js"', '../../js/main.js?v=gallery-20261118"').replace('../../css/main.css"', '../../css/main.css?v=gallery-20261118"')
    (PROJECTS/folder/name).write_text(html,encoding='utf-8')

# ExtruCAD: preserve the original workflow, material list and equation figures.
folder='Pr01-ExtruCAD'
materials=['Al 99.5–99.8','AlMgSi 1','CuZn 37 (Ms63)','Ck10','Ck15','Ck 45 / Cq 45','Cq 22','Cq 35','16 MnCr 5','42 CrMo 4','15 CrNi 6']
render('work-06.html','ExtruCAD','Cold extrusion calculations,<br>in one engineering workspace.','Engineering software / MATLAB / March 2022',
       'A MATLAB application that connects product geometry and material selection to extrusion forces, press capacity, starting billet dimensions and a die-assembly sketch.',
       ['MATLAB GUI','4 product types','11 materials','Cold forming'],('gui.png','ExtruCAD interface: product selection, dimensional inputs, plots and calculated outputs.'),
       [('4','supported product configurations'),('11','material options'),('MATLAB','calculation and interface'),('2022','project completed in March')],[
section('overview','From product dimensions to process requirements','''<p>Cold extrusion forms a billet by applying compressive force through a punch-and-die arrangement. ExtruCAD brings the associated engineering calculations into a single interface, so a selected product and material can be evaluated with consistent dimensional inputs.</p><p>The project focuses on press tonnage, forces acting on the workpiece, initial billet diameter and height, and the corresponding die assembly. Its calculation model uses idealized extrusion relationships and conservation of volume.</p>'''+figure('work-06.jpg','Cold-extrusion equipment context from the original project.')),
section('inputs','Products, materials and inputs','''<p>The user supplies a product type, a material and the final product dimensions. The interface displays the drawing associated with that product so the dimensional labels can be interpreted before calculation.</p>'''+table('Supported product configurations',['Configuration'],[[v] for v in ['CAN','CAN–CAN','ROD','ROD–ROD']])+'''<h3>Material library</h3><p>The original program includes the following eleven material options.</p><ul class="material-list">'''+''.join('<li>'+m+'</li>' for m in materials)+'</ul>'),
section('model','The calculation model','''<p>The figures below retain the original notation and equations. They cover the geometry, principal strain, extrusion force, deformation efficiency and permissible strain used by the program.</p><h3>Notation and strain</h3>'''+gallery([('nomenclature.png','Symbols and geometry used in the extrusion calculation.'),('principalStrain.png','Principal-strain relationships in the original model.')])+'''<h3>Forces and deformation efficiency</h3>'''+figure('force.png','Extrusion-force relationships used by the calculation.')+gallery([('deformationEfficiencyForward.png','Deformation-efficiency relationship for forward extrusion.'),('deformationEfficiencyBackward.png','Deformation-efficiency relationship for backward extrusion.')])+figure('permissibleStrain.png','Permissible-strain relationships used in the original project.')),
section('workflow','Working through an example','''<p>The original walkthrough uses a CAN product and an Al 99.8 selection. The example dimensions are a = 50 mm, b = 40 mm, c = 20 mm and d = 5 mm.</p><h3>1. Select the product and material</h3>'''+gallery([('selectProdcutType.png','Step 1: choose CAN from the product selector.'),('selectMaterial.png','Step 2: select the aluminium material.')])+'''<h3>2. Enter the final dimensions</h3><p>Use the labels in the product drawing to map each dimension to the correct field. Inputs in the interface are expressed in millimetres.</p>'''+figure('insertDimensions.png','Step 3: enter the dimensions shown in the product drawing.')+'''<h3>3. Calculate and inspect the output</h3><p>Select CALCULATE to populate the output fields.</p>'''+figure('calculateresults.png','Step 4: run the calculation using the selected inputs.')),
section('results','Outputs and die assembly','''<p>The result panel brings together material parameters, machine capacity, forward and backward forces, and the starting specimen dimensions. In the illustrated CAN example, the original output reports zero forward force and presents the backward-extrusion result.</p>'''+figure('outputs.png','Calculated output panel for the CAN example.')+'''<h3>Inspect the die arrangement</h3><p>The DIE ASSEMBLY control displays a sketch corresponding to the chosen product.</p>'''+figure('showDieAssebly.png','Die-assembly sketch for the selected product.')+'''<h3>Finish the session</h3><p>Use the Exit control after reviewing the calculation.</p>'''+figure('Exit.png','Exit control in the original MATLAB application.')),
section('outcome','What the project demonstrates','''<p>ExtruCAD connects a set of engineering equations to a practical selection-and-calculation workflow. The product drawing, material choice and numerical outputs are presented together, making the calculation easier to inspect and repeat.</p><p>The screenshots document the original MATLAB implementation. They illustrate its workflow and model outputs; this report does not present a new experimental validation of press loading or production performance.</p>''')],
('https://github.com/mahmoudsamhoud/ExtruCAD','View the ExtruCAD repository'))

# Inline-engine kinematics: all original equation and comparison images retained.
folder='Pr02-Motion-Analysis'
render('work-07.html','Motion Analysis','One mechanism.<br>Two ways to evaluate its motion.','Mechanical simulation / MATLAB &amp; SolidWorks / February 2020',
       'A kinematic study of an inline-engine crank-slider mechanism, comparing analytical MATLAB results with a SolidWorks motion model.',
       ['Crank-slider mechanism','Position','Velocity','Acceleration'],('solidAssembly.png','SolidWorks assembly used for the inline-engine motion study.'),
       [('1 DoF','single-input mechanism'),('2 tools','MATLAB and SolidWorks'),('3 outputs','position, velocity and acceleration'),('2020','project completed in February')],[
section('overview','A common model for two analysis tools','''<p>The project examines the crank-slider mechanism used in an inline engine. Its purpose is to calculate piston and connecting-rod motion in MATLAB, simulate the same mechanism in SolidWorks, and compare the results at a shared operating position.</p><p>The original report includes the mechanism geometry, analytical relationships, model assumptions, software outputs and a comparison at one complete crank revolution.</p>'''+gallery([('work-07.jpg','Inline-engine context from the original project.'),('inlineEngine.png','Inline-engine arrangement used to introduce the motion study.') ])),
section('mechanism','How the crank-slider moves','''<p>A rotating crank drives a connecting rod, which constrains the slider to reciprocate along its guide. The crank, connecting rod, slider and fixed frame form the mechanism studied here.</p><p>Top dead centre and bottom dead centre mark the extreme slider positions. The distance between them is the stroke. At these positions the crank and connecting rod are collinear.</p>'''+figure('crankSlider.png','Crank-slider mechanism showing the crank, connecting rod and slider.')+'''<h3>One degree of freedom</h3><p>The planar model contains four links, three revolute joints and one prismatic joint. Its mobility calculation gives one degree of freedom, so one actuator defines the motion.</p><p class="formula-text">DoF = 3(L − 1) − 2R − 2P − H<br>= 3(4 − 1) − 2(3) − 2(1) − 0 = 1</p>'''),
section('equations','Building the analytical model','''<p>The original equation figures provide the definitions and relationships used to calculate position, velocity and acceleration. Keeping the geometry and sign conventions consistent is essential when comparing the two software models.</p>'''+gallery([('Nomenclature.png','Symbols used in the kinematic equations.'),('KinematicDiagram.png','Kinematic diagram and geometric relationships.')])+figure('positionAnalysis.png','Analytical position relationships for the crank-slider.')+figure('velocityAnalysis.png','Velocity relationships derived from the position model.')+figure('accAnlysis.png','Acceleration relationships used in the analytical model.')),
section('case-study','Defining the comparison case','''<p>The case study starts with the crank and connecting rod collinear at an extreme position. The original model assumptions and the starting configuration are shown below.</p>'''+gallery([('caseStudy.png','Initial collinear configuration for the case study.'),('assumptions.png','Geometric and motion assumptions supplied to the case study.')])+'''<p>The comparison uses the reported instant t = 2 s, corresponding to a crank angle of 2π rad (360°). The two result sets are compared at that same mechanism configuration.</p>'''),
section('matlab','Analytical results in MATLAB','''<p>A MATLAB interface presents the kinematic results in terms of input crank angle. The original plots document the slider and coupler response for the chosen geometry and motion inputs.</p>'''+figure('gui.png','MATLAB interface built for the inline-engine kinematic study.')+figure('MatlabPosition.png','MATLAB position results versus the input crank angle.')+figure('MatlabVelocity.png','MATLAB velocity results versus the input crank angle.')+figure('MatlabAcc.png','MATLAB acceleration results versus the input crank angle.')),
section('solidworks','Motion-study results in SolidWorks','''<p>The 3D assembly was used to produce time-based motion results. The following plots show the piston and coupler separately, grouped by the quantity being measured.</p><h3>Position</h3>'''+gallery([('SolidPositionPiston.png','SolidWorks piston position versus time.'),('SolidPositionCoupler.png','SolidWorks coupler position versus time.')])+'''<h3>Velocity</h3>'''+gallery([('SolidVelocityPiston.png','SolidWorks piston velocity versus time.'),('SolidVelocityCoupler.png','SolidWorks coupler velocity versus time.')])+'''<h3>Acceleration</h3>'''+gallery([('solidAccPiston.png','SolidWorks piston acceleration versus time.'),('solidAccCoupler.png','SolidWorks coupler acceleration versus time.')])),
section('comparison','Comparing the same instant','''<p>The original position plots use different coordinate origins, so they are not compared directly. Velocity and acceleration are evaluated at the reported common configuration, with corresponding quantities and conventions.</p>'''+table('Reported comparison at t = 2 s and θ = 360°',['Quantity','Reported agreement'],[['Slider velocity','Zero in both models at the extreme position'],['Acceleration magnitude','Approximately 298 mm/s² in both models']])+figure('velocityComparison.png','MATLAB and SolidWorks velocity comparison at the selected instant.')+figure('accComparison.png','Acceleration comparison showing the reported magnitude of approximately 298 mm/s².')+'''<p>The comparison illustrates agreement at the documented case-study point. It should not be read as a quantified validation over every angle or every possible geometry.</p>'''),
section('outcome','What the comparison shows','''<p>MATLAB exposes the analytical relationships with crank angle, while SolidWorks visualizes the assembly and provides time-based motion results. Aligning the operating point makes the two approaches useful checks on one another.</p><p>The project demonstrates a complete kinematic workflow: define the mechanism, derive the equations, build the models and compare corresponding outputs.</p>''')],
('https://github.com/mahmoudsamhoud/Inline-Engine-Analysis','View the motion-analysis repository'))

# Baler plate nesting: retain all reported counts, stock sizes and utilization.
folder='Pr03-Nesting-Plates'
head=['Plates','Dimensions (mm)','Parts','Utilization']
nw20=[['1','6000 × 2400','28','76.488%'],['1','3600 × 3000','18','81.861%'],['1','3600 × 2400','35','68.366%']]
nf20=[['1','6000 × 2400','26','82.27%'],['1','3600 × 3000','30','63.52%'],['1','3600 × 2400','25','81.65%']]
render('work-05.html','Nesting Plates','Arranging 91 parts.<br>Making better use of each plate.','Mechanical design / Manufacturing / September 2021',
       'A plate-nesting study for two baler body assemblies, comparing NestingWorks and NestFab across three material thicknesses and available stock sizes.',
       ['91 parts','NestingWorks','NestFab','El-Marakby Steel'],('BalerBodyRightSideMesh.PNG','Right-side baler body: one of the two multi-body assemblies included in the nesting study.'),
       [('91','parts across both assemblies'),('3','plate thicknesses'),('2','nesting tools compared'),('2021','project completed in September')],[
section('overview','Reducing scrap through layout planning','''<p>Nesting arranges multiple part profiles on stock plates to make effective use of the available area. This project applies that process to two multi-body baler parts, balancing available plate sizes with the number and thickness of the required pieces.</p><p>The study was carried out using NestingWorks, a SolidWorks add-in, and NestFab. The aim was to compare feasible layouts and identify practical material-utilization opportunities.</p>'''),
section('parts','Two assemblies, three thicknesses','''<p>The left- and right-side bodies contain 91 parts in total. They are grouped by thickness before nesting so that each layout uses the appropriate stock.</p>'''+figure('BalerBodyLeftSideMesh.PNG','Left-side baler body included in the study.')+table('Part quantities by plate thickness',['Thickness','Number of parts'],[['10 mm','2'],['20 mm','81'],['30 mm','8'],['Total','91']])),
section('stock','Selecting the available stock','''<p>Market research in the original project established the available standard plate dimensions. Those sizes were then evaluated in both nesting tools, with the results compared for utilization and the shape of the remaining material.</p>'''+table('Stock dimensions selected for the study',['Thickness','Part count','Plate dimensions (mm)'],[['10 mm','2','1800 × 1200'],['20 mm','81','6000 × 2400; 3600 × 3000; 3600 × 2400'],['30 mm','8','3600 × 2100']])+'''<p>For the two 10 mm parts, 1800 × 1200 mm was the smallest available plate selected in the study. The more varied 20 mm set required a combination of three plate sizes.</p>'''),
section('ten-mm','10 mm: the same utilization','''<p>Both tools placed the two 10 mm parts on a single 1800 × 1200 mm plate. The reported utilization was the same.</p>'''+table('10 mm comparison',['Tool']+head,[['NestingWorks','1','1800 × 1200','2','25.27%'],['NestFab','1','1800 × 1200','2','25.27%']])+gallery([('thickness10NestingWorks.png','10 mm layout in NestingWorks: two parts, 25.27% utilization.'),('thickness10NestFab.png','10 mm layout in NestFab: two parts, 25.27% utilization.')])),
section('twenty-mm','20 mm: comparing three-plate layouts','''<p>The 81 parts were distributed differently by the two tools. The tables retain each plate’s reported part count and utilization, allowing the layouts to be compared without treating an unweighted average as total utilization.</p><h3>NestingWorks</h3>'''+table('NestingWorks — 20 mm plates',head,nw20)+gallery([('thickness20NestingWorksSh01.png','NestingWorks plate 1: 6000 × 2400 mm, 28 parts, 76.488% utilization.'),('thickness20NestingWorksSh02.png','NestingWorks plate 2: 3600 × 3000 mm, 18 parts, 81.861% utilization.')])+figure('thickness20NestingWorksSh03.png','NestingWorks plate 3: 3600 × 2400 mm, 35 parts, 68.366% utilization.')+'''<h3>NestFab</h3>'''+table('NestFab — 20 mm plates',head,nf20)+gallery([('thickness20NestFabSh01.png','NestFab plate 1: 6000 × 2400 mm, 26 parts, 82.27% utilization.'),('thickness20NestFabSh02.png','NestFab plate 2: 3600 × 3000 mm, 30 parts, 63.52% utilization.')])+figure('thickness20NestFabSh03.png','NestFab plate 3: 3600 × 2400 mm, 25 parts, 81.65% utilization.')+'''<div class="case-note"><strong>Look at the remnant as well as the percentage.</strong> The NestFab layout on the second plate leaves a regular rectangular area. Its shape is useful when considering how remaining stock might be used later.</div>'''),
section('thirty-mm','30 mm: matching reported results','''<p>Both tools arranged the eight 30 mm parts on one 3600 × 2100 mm plate, with a reported utilization of 65.422%.</p>'''+table('30 mm comparison',['Tool']+head,[['NestingWorks','1','3600 × 2100','8','65.422%'],['NestFab','1','3600 × 2100','8','65.422%']])+gallery([('thickness30NestingWorks.png','30 mm layout in NestingWorks: eight parts, 65.422% utilization.'),('thickness30NestFab.png','30 mm layout in NestFab: eight parts, 65.422% utilization.')])),
section('findings','What the layout comparison revealed','''<p>The tools reported the same utilization for the 10 mm and 30 mm sets. The 20 mm layouts showed the more meaningful differences: part distribution, per-plate utilization and the geometry of the remaining stock.</p><p>The original study favored the NestFab 20 mm arrangement, noting slightly better utilization and the rectangular remnant on the second plate. The individual results are retained above so that readers can inspect the basis of that assessment.</p><p>The practical lesson is to evaluate a nesting layout as a manufacturing decision: available stock size, thickness, complete part coverage and reusable remnants all matter alongside the reported utilization percentage.</p>''')],
('https://grabcad.com/library/baler-bodies-1','View the baler models on GrabCAD'))

